function pack(item) {
  console.log(`pack ${item}`);
  label(item);

  return `${item} ${seal()}`;
}

function label(item) {
  console.log(`label ${item}`);
}

function seal() {
  console.log("seal");

  return "sealed";
}

console.log("start");
console.log(pack("mug"));
console.log("end");
